for (const tab of document.querySelectorAll('.review-tab')) { tab.addEventListener('click', () => setTab(tab.dataset.tab)); tab.addEventListener('keydown', (event) => { if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return; event.preventDefault(); const tabs = [...document.querySelectorAll('.review-tab')]; const index = tabs.indexOf(tab); const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + (event.key === 'ArrowRight' ? 1 : tabs.length - 1)) % tabs.length; setTab(tabs[next].dataset.tab); tabs[next].focus(); }); }
$('#report-download').addEventListener('click', () => { if (!state.report) return; const url = URL.createObjectURL(new Blob([JSON.stringify(state.report, null, 2)], { type: 'application/json' })); const link = el('a'); link.href = url; link.download = `review-analysis-${state.demo}.json`; document.body.append(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); });
async function init() { resetChecklist('lookup'); resetWorkspace('lookup'); try { const response = await fetch('/api/demos'); if (response.ok) { const data = await response.json(); state.defaultChecklist = data.checklistDraft; state.demos = arr(data.demos || data); if (state.demos.length) { const select = clear($('#demo-select')); for (const demo of state.demos) { const option = el('option', '', demo.label || demo.name || demo.id); option.value = demo.id; select.append(option); } const initial = state.demos.some((demo) => demo.id === 'lookup') ? 'lookup' : state.demos[0].id; select.value = initial; resetChecklist(initial); resetWorkspace(initial); $('#demo-description').textContent = state.demos.find((demo) => demo.id === initial)?.description || 'Provided source fixtures · baseline → candidate'; } } } catch { /* Analyze provides the actionable connection error. */ } await analyze({ checklist: null }); }
init();
